package com.labloop.web;
import org.springframework.boot.*; import org.springframework.boot.autoconfigure.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.web.bind.annotation.*; import java.util.*;
@SpringBootApplication public class LabLoopApplication { public static void main(String[] a){SpringApplication.run(LabLoopApplication.class,a);} }
@RestController @RequestMapping("/api") class LabApi { private final JdbcTemplate db; LabApi(JdbcTemplate db){this.db=db;} @GetMapping("/equipment") List<Map<String,Object>> equipment(){return db.queryForList("select * from equipment order by code");} @PostMapping("/equipment") Map<String,Object> add(@RequestBody Map<String,String> x){db.update("insert into equipment(code,name,category,status,condition_state,location) values(?,?,?,'AVAILABLE','GOOD',?)",x.get("code"),x.get("name"),x.getOrDefault("category","General"),x.getOrDefault("location","Lab"));return Map.of("ok",true);}@PostMapping("/equipment/{id}/{action}") Map<String,Object> action(@PathVariable long id,@PathVariable String action,@RequestBody(required=false) Map<String,String> body){String state=switch(action){case "borrow"->"BORROWED";case "return"->"AVAILABLE";case "inspect"->"MAINTENANCE";default->throw new IllegalArgumentException("Unknown action");}; String condition=body==null?"GOOD":body.getOrDefault("condition","GOOD");db.update("update equipment set status=?,condition_state=? where id=?",state,condition,id);db.update("insert into activity(equipment_id,action,person,note) values(?,?,?,?)",id,action,body==null?"Lab Assistant":body.getOrDefault("person","Lab Assistant"),body==null?"":body.getOrDefault("note",""));return Map.of("ok",true);}@GetMapping("/equipment/{id}/history") List<Map<String,Object>> history(@PathVariable long id){return db.queryForList("select action,person,note,created_at from activity where equipment_id=? order by created_at desc",id);} }
